from scipy.optimize import least_squares
A=df['A'].values;t=df['t'].values;y=df['dA_dt'].values
fams={'exp':lambda t,a:np.exp(-a*t),'sin':lambda t,a:np.sin(a*t),'cos':lambda t,a:np.cos(a*t),'pow':lambda t,a:t**a,'expgrow':lambda t,a:np.exp(a*t)}
rng=np.random.default_rng(0)
out=[]
for f1 in fams:
  for f2 in fams:
    best=None
    for trial in range(25):
        x0=[rng.normal(),rng.normal(),rng.uniform(0.05,3),rng.normal(),rng.normal(),rng.uniform(0.05,3),rng.normal()]
        def m(p):
            return p[0]*A**3+p[1]*fams[f1](t,p[2])*A**p[3]+p[4]*fams[f2](t,p[5])*A**p[6]
        try:
            s=least_squares(lambda p:m(p)-y,x0)
        except Exception as e: continue
        if not np.isfinite(s.cost): continue
        nm=2*s.cost/np.sum((y-y.mean())**2)
        if best is None or nm<best[0]: best=(nm,np.round(s.x,4))
    out.append((best[0],f1,f2,best[1]))
out.sort(key=lambda x:x[0])
for o in out[:6]: print(o)

